SELECT CASE state WHEN 'Active' THEN 'active' WHEN 'Closed' THEN 'churned' WHEN 'Hold' THEN 'suspended' END AS "customer_status", AVG(FLOOR(ABS(CAST(credit_limit AS DECIMAL(38, 6)) / CAST(5000 AS DECIMAL(38, 6))) + 0.5) * SIGN(CAST(credit_limit AS DECIMAL(38, 6)) / CAST(5000 AS DECIMAL(38, 6))) * 5000) AS "credit_limit_r5000_avg" FROM accounts WHERE opened_at >= CAST('2026-08-25 15:00:00' AS TIMESTAMP) AND opened_at < CAST('2026-11-25 15:00:00' AS TIMESTAMP) GROUP BY CASE state WHEN 'Active' THEN 'active' WHEN 'Closed' THEN 'churned' WHEN 'Hold' THEN 'suspended' END LIMIT 50